import json
d=json.load(open('/inputs/mewt-results.json'))

ids = sorted(r['mutant']['id'] for r in d['results'])
by_target = {}
for r in d['results']:
    p = r['target']['path']
    by_target.setdefault(p, []).append(r['mutant']['id'])
for k in by_target:
    by_target[k] = sorted(by_target[k])

campaign = {
    "total": 29,
    "tested": 24,
    "caught": 16,
    "uncaught": 8,
    "timeout": 0,
    "skipped": 5
}

summary = {
    "campaign": campaign,
    "exported_uncaught_ids": ids,
    "exported_uncaught_by_target": by_target,
    "kill_rate": {
        "numerator": campaign["caught"],
        "denominator": campaign["caught"] + campaign["uncaught"]
    },
    "equivalence": "not_assessed"
}

with open('/work/mutation-summary.json','w') as f:
    json.dump(summary, f, indent=2)

print(json.dumps(summary, indent=2))
